	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void aSelectedKernelCannotDropTheBuildPatternsExecutableRange(boolean interpreted) throws Exception {
		Map<Value, Integer> expected = new LinkedHashMap<>();
		for (int i = FIRST; i < ROWS; i++) {
			expected.put(SimpleValueFactory.getInstance().createLiteral(i), 1);
		}
		assertThat(bag(memoryRepository)).as("explicit accepted numeric domain on MemoryStore").isEqualTo(expected);
		set(NATIVE, "false");
		assertThat(bag(repository)).as("generic LMDB retains the same exact range").isEqualTo(expected);
		set(NATIVE, "true");
		String route = interpreted ? LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED
				: LmdbNativeAttemptMetrics.PATH_IR_KERNEL;
		Optimized optimized = optimizeAndRun(route);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			var triples = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			LmdbNativeEvaluationStrategy strategy = spy(new LmdbNativeEvaluationStrategy(triples, null, null, 0L,
					new EvaluationStatistics(), false));
			doReturn(route).when(strategy).forcedExecutionStrategyName();
			TupleExpr parsed = optimized.expression();
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(parsed,
					new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);
			assertThat(compiled).isInstanceOf(NativeRowsStep.class);
			NativeRowsStep step = (NativeRowsStep) compiled;
			assertThat(step.arg).isInstanceOf(MultiJoinPlan.class);
			MultiJoinPlan join = (MultiJoinPlan) step.arg;
			assertThat(join.filters).as("the pushed range replaces, rather than merely accompanies, its FILTER")
					.isEmpty();
			List<PatternPlan> ranged = List.of(join.children)
					.stream()
					.filter(PatternPlan.class::isInstance)
					.map(PatternPlan.class::cast)
					.filter(pattern -> pattern.range != null)
					.toList();
			assertThat(ranged).as("one normally compiled executable numeric range").hasSize(1);
			PatternPlan rangedBuild = ranged.getFirst();
			assertThat(rangedBuild.statementOrder).isNull();
			RowState row = new RowState(step.source, step.layout, EmptyBindingSet.getInstance());
			try {
				assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, row.source, row.layout)).isTrue();
				LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerRows(step.arg, row, parsed,
						false);
				assertThat(lowered).isNotNull();
				List<LmdbNativeKernelIr.Node> nodes = new ArrayList<>();
				LmdbNativeKernelIr.visitNodes(lowered.kernel.pipeline, nodes::add);
				List<LmdbNativeKernelIr.HashBuild> builds = nodes.stream()
						.filter(LmdbNativeKernelIr.HashBuild.class::isInstance)
						.map(LmdbNativeKernelIr.HashBuild.class::cast)
						.toList();
				assertThat(builds).as("the real range-bearing build remains in the selected hash plan").hasSize(1);
				List<LmdbNativeKernelIr.Node> buildNodes = new ArrayList<>();
				LmdbNativeKernelIr.visitNodes(builds.getFirst().pipeline, buildNodes::add);
				assertThat(buildNodes).as("a ranged build without an adjacency view is enumerated by its scan")
						.anyMatch(LmdbNativeKernelIr.ScanQuad.class::isInstance);
				assertThat(lowered.bindings.scanSites)
						.anySatisfy(site -> assertThat(site.range())
								.as("the scan uses the exact executable range selected by the optimizer")
								.isEqualTo(rangedBuild.range));
				assertThat(nodes).anyMatch(LmdbNativeKernelIr.HashProbe.class::isInstance);
				assertThat(lowered.kernel.resumable).isTrue();
			} finally {
				row.memoryScope.close();
			}
			List<String> selected = new ArrayList<>();
			long binds = interpreted ? LmdbNativeKernelExecution.INTERPRETED_BINDS.get()
					: LmdbNativeKernelExecution.COMPILED_BINDS.get();
			long hashBefore = LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get();
			LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
				if (record.point() == LmdbNativeDecisionPoint.ROW) {
					selected.add(id);
				}
			});
			Map<Value, Integer> actual = new LinkedHashMap<>();
			try (var rows = compiled.evaluate(EmptyBindingSet.getInstance())) {
				while (rows.hasNext()) {
					actual.merge(rows.next().getValue("n"), 1, Integer::sum);
				}
			} finally {
				LmdbNativeDispatchLoop.observeSelections(null);
			}
			assertThat(selected).as("the requested tier really opened successfully").containsExactly(route);
			assertThat(interpreted ? LmdbNativeKernelExecution.INTERPRETED_BINDS.get()
					: LmdbNativeKernelExecution.COMPILED_BINDS.get()).isGreaterThan(binds);
			assertThat(LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get()).isGreaterThan(hashBefore);
			System.out.printf("range route=%s hash=true expectedRows=%d actualRows=%d index=%s%n", route,
					expected.size(), actual.size(), rangedBuild.indexName);
			assertThat(optimized.bag()).as("the ordinary optimized repository route must retain the executable range")
					.isEqualTo(expected);
			assertThat(actual).as("an opened row kernel must not widen a range-bearing build's answer bag")
					.isEqualTo(expected);
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void aPlainHashBuildRetainsItsLegalRangedProbe(boolean interpreted) throws Exception {
		var vf = SimpleValueFactory.getInstance();
		IRI build = vf.createIRI(NS + "smallBuild"), yes = vf.createIRI(NS + "yes");
		Map<Value, Integer> expected = new LinkedHashMap<>();
		for (int i = FIRST; i < FIRST + ROWS / 4; i++) {
			expected.put(vf.createLiteral(i), 1);
		}
		// Add this plane only in the preservation control. The original ranged-build defect fixtures stay intact.
		for (SailRepository target : List.of(repository, memoryRepository)) {
			try (var connection = target.getConnection()) {
				connection.begin();
				for (int i = FIRST; i < FIRST + ROWS / 4; i++) {
					connection.add(vf.createIRI(NS + "s" + i), build, yes);
				}
				connection.commit();
			}
		}
		assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		String query = "SELECT ?n WHERE { ?s <" + build + "> <" + yes + "> . ?s <" + NS
				+ "probe> ?n . FILTER(?n >= " + FIRST + ") }";
		assertThat(bag(memoryRepository, query)).as("the explicit 256-row ranged-probe bag").isEqualTo(expected);
		set(NATIVE, "false");
		assertThat(bag(repository, query)).as("generic LMDB ranged-probe bag").isEqualTo(expected);
		set(NATIVE, "true");
		String route = interpreted ? LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED
				: LmdbNativeAttemptMetrics.PATH_IR_KERNEL;
		Optimized optimized = optimizeAndRun(route, query);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			long buildPredicate = source.idOf(build);
			var triples = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			LmdbNativeEvaluationStrategy strategy = spy(new LmdbNativeEvaluationStrategy(triples, null, null, 0L,
					new EvaluationStatistics(), false));
			doReturn(route).when(strategy).forcedExecutionStrategyName();
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(optimized.expression(),
					new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);
			assertThat(compiled).isInstanceOf(NativeRowsStep.class);
			NativeRowsStep step = (NativeRowsStep) compiled;
			assertThat(step.arg).isInstanceOf(MultiJoinPlan.class);
			MultiJoinPlan join = (MultiJoinPlan) step.arg;
			assertThat(join.filters).isEmpty();
			List<PatternPlan> ranged = List.of(join.children)
					.stream()
					.filter(PatternPlan.class::isInstance)
					.map(PatternPlan.class::cast)
					.filter(pattern -> pattern.range != null)
					.toList();
			assertThat(ranged).hasSize(1);
			RowState row = new RowState(step.source, step.layout, EmptyBindingSet.getInstance());
			try {
				assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, row.source, row.layout)).isTrue();
				var lowered = LmdbNativeKernelLowering.lowerRows(step.arg, row, optimized.expression(), false);
				assertThat(lowered).isNotNull();
				List<LmdbNativeKernelIr.Node> nodes = new ArrayList<>();
				LmdbNativeKernelIr.visitNodes(lowered.kernel.pipeline, nodes::add);
				List<LmdbNativeKernelIr.HashBuild> builds = nodes.stream()
						.filter(LmdbNativeKernelIr.HashBuild.class::isInstance)
						.map(LmdbNativeKernelIr.HashBuild.class::cast)
						.toList();
				assertThat(builds).as("the legal non-ranged hash build must remain admitted").hasSize(1);
				List<LmdbNativeKernelIr.Node> buildNodes = new ArrayList<>();
				LmdbNativeKernelIr.visitNodes(builds.getFirst().pipeline, buildNodes::add);
				assertThat(buildNodes).anySatisfy(node -> {
					assertThat(node).isInstanceOf(LmdbNativeKernelIr.Probe.class);
					var probe = (LmdbNativeKernelIr.Probe) node;
					assertThat(lowered.bindings.adjacencies[probe.adjacency].predicate).isEqualTo(buildPredicate);
				});
				assertThat(nodes).anyMatch(LmdbNativeKernelIr.HashProbe.class::isInstance);
				assertThat(nodes).anyMatch(LmdbNativeKernelIr.ScanQuad.class::isInstance);
				assertThat(lowered.bindings.scanSites)
						.anySatisfy(site -> assertThat(site.range()).isEqualTo(ranged.getFirst().range));
				assertThat(lowered.kernel.resumable).isTrue();
			} finally {
				row.memoryScope.close();
			}
			List<String> selected = new ArrayList<>();
			long binds = interpreted ? LmdbNativeKernelExecution.INTERPRETED_BINDS.get()
					: LmdbNativeKernelExecution.COMPILED_BINDS.get();
			long hashBefore = LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get();
			LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
				if (record.point() == LmdbNativeDecisionPoint.ROW) {
					selected.add(id);
				}
			});
			Map<Value, Integer> actual = new LinkedHashMap<>();
			try (var rows = compiled.evaluate(EmptyBindingSet.getInstance())) {
				while (rows.hasNext()) {
					actual.merge(rows.next().getValue("n"), 1, Integer::sum);
				}
			} finally {
				LmdbNativeDispatchLoop.observeSelections(null);
			}
			assertThat(selected).containsExactly(route);
			assertThat(interpreted ? LmdbNativeKernelExecution.INTERPRETED_BINDS.get()
					: LmdbNativeKernelExecution.COMPILED_BINDS.get()).isGreaterThan(binds);
			assertThat(LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get()).isGreaterThan(hashBefore);
			assertThat(optimized.bag()).as("ordinary optimized hash with a ranged probe").isEqualTo(expected);
			assertThat(actual).as("the opened hash retains the probe's executable range").isEqualTo(expected);
		}
	}

	private Optimized optimizeAndRun(String route) {
		return optimizeAndRun(route, QUERY);
	}

	/** Reuse real optimizer statistics and algebra, not an unoptimized parser tree or invented cardinalities. */
	private Optimized optimizeAndRun(String route, String query) {
		List<TupleExpr> optimized = new ArrayList<>();
		Map<Value, Integer> bag = new LinkedHashMap<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (record.point() == LmdbNativeDecisionPoint.ROW) {
				assertThat(id).isEqualTo(route);
				assertThat(target).isNotNull();
				optimized.add(target.clone());
			}
		});
		try (var connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setForcedLmdbExecutionStrategy(route);
			prepared.setMaxExecutionTime(10);
			try (var rows = prepared.evaluate()) {
				while (rows.hasNext()) {
					bag.merge(rows.next().getValue("n"), 1, Integer::sum);
				}
			}
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
		}
		assertThat(optimized).as("one actual optimized repository dispatch").hasSize(1);
		return new Optimized(optimized.getFirst(), bag);
	}

	private record Optimized(TupleExpr expression, Map<Value, Integer> bag) {
	}

	private Map<Value, Integer> bag(SailRepository target) {
		return bag(target, QUERY);
	}

	private Map<Value, Integer> bag(SailRepository target, String query) {
		Map<Value, Integer> bag = new LinkedHashMap<>();
		try (var connection = target.getConnection(); var rows = connection.prepareTupleQuery(query).evaluate()) {
			while (rows.hasNext()) {
				bag.merge(rows.next().getValue("n"), 1, Integer::sum);
			}
		}
		return bag;
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}
